const std = @import("std");
fn gitRevision(b: *std.Build) []const u8 {
    // A source archive has no checkout identity, even if extracted inside another repo.
    std.Io.Dir.accessAbsolute(b.graph.io, b.pathFromRoot(".git"), .{}) catch return "unknown";
    var code: u8 = 0;
    const output = b.runAllowFail(&.{ "git", "-C", b.pathFromRoot("."), "rev-parse", "--verify", "HEAD" }, &code, .ignore) catch return "unknown";
    return std.mem.trim(u8, output, "\r\n");
}

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});
    const options = b.addOptions();
    options.addOption([]const u8, "git_commit", gitRevision(b));
    options.addOption([]const u8, "app_version", @import("build.zig.zon").version);
    options.addOption([]const u8, "update_channel", "stable");
    options.addOption(enum { none }, "wasm_surface", .none);
    options.addOption(bool, "loops_shell", true);
    const wasmtime = @import("native/wasmtime_build.zig").dependency(b, target) orelse return;
    const app_options = options.createModule();
    const session_options = b.addOptions();
    session_options.addOption(bool, "hooks", false);
    session_options.addOption([]const u8, "trace_dir", "");
    session_options.addOption([]const u8, "src_dir", b.pathFromRoot("vendor/fx/src/core/session_manager"));
    const session = b.createModule(.{ .root_source_file = b.path("vendor/fx/src/core/session_manager/api.zig"), .target = target, .optimize = optimize, .link_libc = true });
    session.addImport("build_options", session_options.createModule());
    const app = b.createModule(.{ .root_source_file = b.path("fh_main.zig"), .target = target, .optimize = optimize, .link_libc = true, .stack_check = false, .stack_protector = false, .omit_frame_pointer = true, .unwind_tables = .none, .error_tracing = false, .strip = optimize != .Debug });
    app.addImport("build_options", app_options);
    app.addImport("session_manager", session);
    @import("native/wasmtime_build.zig").link(app, wasmtime, target);
    const exe = b.addExecutable(.{ .name = "fh", .root_module = app });
    b.installArtifact(exe);
    b.step("dev", "Build the native Debug CLI").dependOn(&b.addInstallArtifact(exe, .{}).step);
    const check = b.addExecutable(.{ .name = "fh-check", .root_module = app });
    b.step("check", "Type-check the native CLI without code generation or linking").dependOn(&check.step);
    const run = b.addRunArtifact(exe);
    if (b.args) |args| run.addArgs(args);
    b.step("run", "Run native fh").dependOn(&run.step);
    const tests = b.createModule(.{ .root_source_file = b.path("native_tests.zig"), .target = target, .optimize = optimize, .link_libc = true });
    tests.addImport("build_options", app_options);
    @import("native/wasmtime_build.zig").link(tests, wasmtime, target);
    const wasm_unit = b.addTest(.{ .root_module = tests, .filters = &.{"native Wasm"} });
    b.step("test-wasm", "Test the embedded Wasm runtime").dependOn(&b.addRunArtifact(wasm_unit).step);
    const socket_unit = b.addTest(.{ .root_module = tests, .filters = &.{ "native socket", "Docker socket" } });
    b.step("test-sockets", "Check Unix socket identity and Docker path validation").dependOn(&b.addRunArtifact(socket_unit).step);
    const unit = b.addTest(.{ .root_module = tests, .filters = &.{ "native ", "package", "strict JSON", "filesystem snapshot", "bounded HTTP", "Docker", "code ", "decision contract", "decision carry", "exhausted shared", "question and primitive" } });
    const test_run = b.addRunArtifact(unit);
    // fh-workspace/1 steps run real commands through fx's command runner, which re-executes
    // the product as its foreground session. A test binary cannot stand in for it.
    test_run.step.dependOn(&b.addInstallArtifact(exe, .{}).step);
    test_run.setEnvironmentVariable("FX_TEST_PRODUCT_EXE", b.getInstallPath(.bin, "fh"));
    b.step("test-loops-native", "Check native Loops packages, validation and execution").dependOn(&test_run.step);
    b.step("test", "Run native Loop tests").dependOn(&test_run.step);
    const chat = b.createModule(.{ .root_source_file = b.path("fh_tests.zig"), .target = target, .optimize = optimize, .link_libc = true });
    chat.addImport("build_options", app_options);
    chat.addImport("session_manager", session);
    @import("native/wasmtime_build.zig").link(chat, wasmtime, target);
    const chat_unit = b.addTest(.{ .root_module = chat, .filters = &.{ "fh ", "chat completions" } });
    b.step("test-chat", "Check fx native conversation composition").dependOn(&b.addRunArtifact(chat_unit).step);
    const browser_live = b.addSystemCommand(&.{ "python3", "tests/native/local_browser_loop.py", "--binary" });
    browser_live.addArtifactArg(exe);
    browser_live.addArgs(&.{ "--out", b.pathFromRoot(".zig-cache/browser-local-evidence") });
    if (b.option([]const u8, "moli", "Installed Moli binary for the controlled localhost browser test")) |moli| browser_live.addArgs(&.{ "--moli", moli });
    b.step("test-browser-local", "Run real installed Moli with a disposable localhost page and deterministic provider").dependOn(&browser_live.step);
    const portable_examples = b.addSystemCommand(&.{ "python3", "tests/native/portable_examples.py", "--binary" });
    portable_examples.addArtifactArg(exe);
    b.step("test-portable-examples", "Check shipped Wasm examples, compatibility and CLI diagnostics without source runtimes").dependOn(&portable_examples.step);
    const startup_unit = b.addTest(.{ .root_module = chat, .filters = &.{ "fh provider focused fixtures", "fh startup" } });
    const startup_step = b.step("test-startup", "Check native startup behavior");
    startup_step.dependOn(&b.addRunArtifact(startup_unit).step);
    const startup_native = b.addTest(.{ .root_module = tests, .filters = &.{"native startup"} });
    startup_step.dependOn(&b.addRunArtifact(startup_native).step);
    const bundle_readme = std.mem.replaceOwned(u8, b.allocator, @embedFile("README.md"), "(vendor/fx/", "(licenses/fx/") catch @panic("OOM");
    const bundle_readme_links = std.mem.replaceOwned(u8, b.allocator, bundle_readme, "(patches/fx/README.md)", "(docs/fx-provenance.md)") catch @panic("OOM");
    const bundle_prompt_links = std.mem.replaceOwned(u8, b.allocator, bundle_readme_links, "(native/conversation_prompt.md)", "(docs/conversation-prompt.md)") catch @panic("OOM");
    const generated = b.addWriteFiles();
    const readme = generated.add("README.md", bundle_prompt_links);
    const bundle = b.step("bundle", "Install native fh, Loop packages, skills and upstream notices");
    bundle.dependOn(&b.addInstallArtifact(exe, .{ .dest_dir = .{ .override = .{ .custom = "" } } }).step);
    bundle.dependOn(&b.addInstallDirectory(.{ .source_dir = b.path("licenses"), .install_dir = .prefix, .install_subdir = "licenses" }).step);
    inline for (.{ "LICENSE", "NOTICE", "CONTRIBUTING.md", "SECURITY.md" }) |file| bundle.dependOn(&b.addInstallFileWithDir(b.path(file), .prefix, file).step);
    bundle.dependOn(&b.addInstallFileWithDir(readme, .prefix, "README.md").step);
    inline for (.{ "loops", "skills" }) |directory| bundle.dependOn(&b.addInstallDirectory(.{ .source_dir = b.path(directory), .install_dir = .prefix, .install_subdir = directory }).step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("docs/batch-evaluation.md"), .prefix, "docs/batch-evaluation.md").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("docs/packages.md"), .prefix, "docs/packages.md").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("docs/privacy.md"), .prefix, "docs/privacy.md").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("docs/model-setup.md"), .prefix, "docs/model-setup.md").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("docs/publication.md"), .prefix, "docs/publication.md").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("docs/releasing.md"), .prefix, "docs/releasing.md").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("docs/code-runtimes.md"), .prefix, "docs/code-runtimes.md").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("examples/decision-gate-cases.json"), .prefix, "examples/decision-gate-cases.json").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("docs/workspace-loops.md"), .prefix, "docs/workspace-loops.md").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("examples/workspace-repair-input.json"), .prefix, "examples/workspace-repair-input.json").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("examples/browser-check-input.json"), .prefix, "examples/browser-check-input.json").step);
    bundle.dependOn(&b.addInstallDirectory(.{ .source_dir = b.path("examples/browser-check"), .install_dir = .prefix, .install_subdir = "examples/browser-check" }).step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("examples/browser-capture.json"), .prefix, "examples/browser-capture.json").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("docs/browser-capture.md"), .prefix, "docs/browser-capture.md").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("examples/decision-gate-input.json"), .prefix, "examples/decision-gate-input.json").step);
    bundle.dependOn(&b.addInstallDirectory(.{ .source_dir = b.path("packages/loops-contract"), .install_dir = .prefix, .install_subdir = "packages/loops-contract" }).step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("packages/loops-contract/loop-0.2.schema.json"), .prefix, "lib/packages/loops-contract/loop-0.2.schema.json").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("packages/loops-contract/loop-0.3.schema.json"), .prefix, "lib/packages/loops-contract/loop-0.3.schema.json").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("packages/loops-contract/loop-0.4.schema.json"), .prefix, "lib/packages/loops-contract/loop-0.4.schema.json").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("examples/warm-context-input.json"), .prefix, "examples/warm-context-input.json").step);
    bundle.dependOn(&b.addInstallDirectory(.{ .source_dir = b.path("docs/contracts"), .install_dir = .prefix, .install_subdir = "docs/contracts" }).step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("docs/fh-own-use.md"), .prefix, "docs/fh-own-use.md").step);
    bundle.dependOn(&b.addInstallFileWithDir(b.path("native/conversation_prompt.md"), .prefix, "docs/conversation-prompt.md").step);
    inline for (.{ .{ "docs/loops.md", "docs/loops.md" }, .{ "scripts/install-skills.py", "scripts/install-skills.py" }, .{ "scripts/setup-code-profile.py", "scripts/setup-code-profile.py" }, .{ "packages/loops-contract/loop-0.1.schema.json", "lib/packages/loops-contract/loop-0.1.schema.json" }, .{ "vendor/fx/LICENSE", "licenses/fx/LICENSE" }, .{ "vendor/fx/THIRD_PARTY_NOTICES.md", "licenses/fx/THIRD_PARTY_NOTICES.md" }, .{ "patches/fx/README.md", "docs/fx-provenance.md" } }) |file| bundle.dependOn(&b.addInstallFileWithDir(b.path(file[0]), .prefix, file[1]).step);
}
